from pathlib import Path
import base64,json,subprocess,io
from PIL import Image
ROOT=Path(__file__).resolve().parent.parent;QA=ROOT/'qa/focus-premium';OUT=Path('/workspace/artifacts/Focus-20-skins-20261029.html')
skins=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import {SKINS} from './web/focus-skins.mjs';console.log(JSON.stringify(SKINS.map(({id,name})=>({id,name}))));"],cwd=ROOT))
def encode(path):
 b=io.BytesIO();Image.open(path).save(b,format='WEBP',quality=90,method=5);return 'data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()
screens={s['id']:{theme:{device:encode(QA/f'{s["id"]}-{theme}-{device}.png') for device in ['desktop','phone','tablet']} for theme in ['dark','light']} for s in skins}
markup='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focus — 20 skins</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0e1114;color:#e9eeec;font:14px/1.6 system-ui}main{max-width:1280px;margin:auto;padding:28px 20px 60px}h1{margin:0;font-size:26px;letter-spacing:-.03em}p{color:#a2afb1;font-size:12px}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0;align-items:center}select,button{font:inherit;background:#1a2227;color:#e9eeec;border:1px solid #3b484f;border-radius:9px;padding:9px 12px;min-height:44px;cursor:pointer}button[aria-pressed=true]{background:#b1cbbd;color:#182a20;border-color:transparent}button:focus-visible,select:focus-visible{outline:2px solid #b1cbbd;outline-offset:3px}figure{margin:16px 0;text-align:center}img{max-width:100%;width:100%;display:block;margin:auto;border:1px solid #3b484f;border-radius:14px}figure.phone img{max-width:390px}figure.tablet img{max-width:834px}figcaption{color:#a2afb1;font-size:12px;margin:12px}.prev-next{margin-left:auto;display:flex;gap:6px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:7px;margin-top:16px}.gallery button{font-size:11px;text-align:left;overflow-wrap:anywhere;padding:8px}.gallery button[aria-pressed=true]{font-weight:600}@media(max-width:500px){main{padding:20px 12px}.toolbar{gap:6px}.toolbar select{width:100%}.toolbar button{font-size:12px}.prev-next{margin-left:0}.gallery{grid-template-columns:1fr 1fr}}</style><main><h1>Focus</h1><p>20種類 · 実際のアプリの表示 · 架空データ</p><div class="toolbar"><select id="skin" aria-label="スキン"></select><button data-device="desktop" aria-pressed="true">PC</button><button data-device="phone">iPhone幅</button><button data-device="tablet">iPad幅</button><button id="theme">ライト</button><span class="prev-next"><button id="prev" aria-label="前のスキン">←</button><button id="next" aria-label="次のスキン">→</button></span></div><figure><img alt="Focusのスキン・架空データ"><figcaption></figcaption></figure><div class="gallery"></div><p>設定 → 表示 → スキンの「一覧」から変更できます。全スキンで配置と操作は共通。各端末で異なるスキンを使えます。このページはスクリーンショットの比較用で、入力や計測を行いません。</p></main><script>const skins=SKINS,screens=SCREENS;let index=0,device='desktop',theme='dark';const select=document.querySelector('#skin');select.innerHTML=skins.map(s=>'<option value="'+s.id+'">'+s.name+'</option>').join('');document.querySelector('.gallery').innerHTML=skins.map(s=>'<button data-choice="'+s.id+'">'+s.name+'</button>').join('');function draw(){const skin=skins[index];select.value=skin.id;document.querySelector('img').src=screens[skin.id][theme][device];document.querySelector('figure').className=device;document.querySelector('figcaption').textContent=(index+1)+' / 20 · '+skin.name+' · '+(theme==='dark'?'Dark':'Light');for(const b of document.querySelectorAll('[data-device]'))b.setAttribute('aria-pressed',b.dataset.device===device);for(const b of document.querySelectorAll('[data-choice]'))b.setAttribute('aria-pressed',b.dataset.choice===skin.id);document.querySelector('#theme').textContent=theme==='dark'?'ライト':'ダーク';}select.onchange=()=>{index=skins.findIndex(s=>s.id===select.value);draw()};document.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.choice)index=skins.findIndex(s=>s.id===b.dataset.choice);else if(b.dataset.device)device=b.dataset.device;else if(b.id==='theme')theme=theme==='dark'?'light':'dark';else if(b.id==='prev')index=(index+19)%20;else if(b.id==='next')index=(index+1)%20;else return;draw()};draw();</script></html>'''
OUT.write_text(markup.replace('SKINS',json.dumps(skins)).replace('SCREENS',json.dumps(screens)));print(json.dumps({'file':str(OUT),'bytes':OUT.stat().st_size}))
